(function(){
  var app=document.querySelector('#app')||document.body.firstElementChild;
  var vm=app&&app.__vue__;
  if(!vm) return 'NO_VUE';
  var out={rootKeys:Object.keys(vm.$data||{}).slice(0,20)};
  var found=[];
  function walk(c,d){
    if(d>6||found.length>10) return;
    var dd=c.$data||{};
    if(dd.loginForm) found.push({name:c.$options.name,lf:dd.loginForm});
    (c.$children||[]).forEach(function(k){walk(k,d+1)});
  }
  walk(vm,0);
  out.found=found.map(function(f){return {name:f.name,formKeys:Object.keys(f.lf)}});
  return JSON.stringify(out);
})()
EOF
